"""Persistent article corpus ingestion and chunking for expert RAG."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timezone
from hashlib import sha1
from pathlib import Path
import json

from raap_agent.rag import KnowledgeDocument
from raap_agent.schemas import (
    CorpusChunkSummary,
    CorpusDocumentInput,
    CorpusIngestResponse,
    CorpusListItem,
    CorpusListResponse,
)


def _utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _normalize_text(text: str) -> str:
    return text.replace("\r\n", "\n").replace("\r", "\n").strip()


def _stable_source_id(document: CorpusDocumentInput) -> str:
    source_seed = json.dumps(
        {
            "title": document.title or "",
            "namespace": document.namespace,
            "text": _normalize_text(document.text),
            "source_type": document.source_type,
            "brand": document.brand,
            "platform": document.platform,
            "activity": document.activity,
        },
        ensure_ascii=True,
        sort_keys=True,
    )
    return f"corpus-{sha1(source_seed.encode('utf-8')).hexdigest()[:12]}"


def _content_hash(text: str) -> str:
    return sha1(_normalize_text(text).encode("utf-8")).hexdigest()


@dataclass(slots=True)
class StoredCorpusRecord:
    """Raw corpus record persisted to local storage."""

    source_id: str
    title: str
    text: str
    namespace: str
    source_type: str
    tags: list[str]
    metadata: dict[str, object]
    created_at: str
    content_hash: str

    def to_dict(self) -> dict[str, object]:
        return {
            "source_id": self.source_id,
            "title": self.title,
            "text": self.text,
            "namespace": self.namespace,
            "source_type": self.source_type,
            "tags": self.tags,
            "metadata": self.metadata,
            "created_at": self.created_at,
            "content_hash": self.content_hash,
        }

    @classmethod
    def from_dict(cls, payload: dict[str, object]) -> "StoredCorpusRecord":
        return cls(
            source_id=str(payload.get("source_id", "")),
            title=str(payload.get("title", "")),
            text=str(payload.get("text", "")),
            namespace=str(payload.get("namespace", "cases")),
            source_type=str(payload.get("source_type", "article")),
            tags=[str(item) for item in payload.get("tags", [])] if isinstance(payload.get("tags"), list) else [],
            metadata=payload.get("metadata", {}) if isinstance(payload.get("metadata"), dict) else {},
            created_at=str(payload.get("created_at", _utc_now())),
            content_hash=str(payload.get("content_hash", _content_hash(str(payload.get("text", ""))))),
        )


def _to_record(document: CorpusDocumentInput) -> StoredCorpusRecord:
    source_id = document.source_id or _stable_source_id(document)
    text = _normalize_text(document.text)
    metadata = dict(document.metadata)
    if document.brand:
        metadata["brand"] = document.brand
    if document.platform:
        metadata["platform"] = document.platform
    if document.activity:
        metadata["activity"] = document.activity
    if document.audience:
        metadata["audience"] = document.audience
    if document.style_labels:
        metadata["style_labels"] = list(document.style_labels)
    if document.author:
        metadata["author"] = document.author
    if document.url:
        metadata["url"] = document.url

    return StoredCorpusRecord(
        source_id=source_id,
        title=(document.title or source_id).strip(),
        text=text,
        namespace=document.namespace.strip() or "cases",
        source_type=document.source_type.strip() or "article",
        tags=list(dict.fromkeys([item for item in document.tags if item])),
        metadata=metadata,
        created_at=_utc_now(),
        content_hash=_content_hash(text),
    )


def _window_chunk(text: str, chunk_size: int, chunk_overlap: int) -> list[str]:
    normalized = _normalize_text(text)
    if not normalized:
        return []
    if chunk_overlap >= chunk_size:
        chunk_overlap = max(0, chunk_size // 5)
    step = max(1, chunk_size - chunk_overlap)
    chunks: list[str] = []
    start = 0
    while start < len(normalized):
        end = min(len(normalized), start + chunk_size)
        chunk = normalized[start:end].strip()
        if chunk:
            chunks.append(chunk)
        if end >= len(normalized):
            break
        start += step
    return chunks


def _chunk_text(text: str, chunk_size: int, chunk_overlap: int) -> list[str]:
    normalized = _normalize_text(text)
    if not normalized:
        return []

    paragraphs = [paragraph.strip() for paragraph in normalized.split("\n\n") if paragraph.strip()]
    if not paragraphs:
        return _window_chunk(normalized, chunk_size, chunk_overlap)

    chunks: list[str] = []
    current = ""
    for paragraph in paragraphs:
        if len(paragraph) > chunk_size:
            if current:
                chunks.append(current)
                current = ""
            chunks.extend(_window_chunk(paragraph, chunk_size, chunk_overlap))
            continue

        candidate = paragraph if not current else f"{current}\n\n{paragraph}"
        if len(candidate) <= chunk_size:
            current = candidate
            continue
        if current:
            chunks.append(current)
        current = paragraph
    if current:
        chunks.append(current)
    return chunks


def _build_chunk_documents(
    record: StoredCorpusRecord,
    chunk_size: int,
    chunk_overlap: int,
) -> list[KnowledgeDocument]:
    chunks = _chunk_text(record.text, chunk_size=chunk_size, chunk_overlap=chunk_overlap)
    total_chunks = max(len(chunks), 1)
    documents: list[KnowledgeDocument] = []
    for index, chunk in enumerate(chunks, start=1):
        chunk_seed = f"{record.source_id}:{index}:{chunk}"
        chunk_id = f"chunk-{sha1(chunk_seed.encode('utf-8')).hexdigest()[:12]}"
        metadata = {
            **record.metadata,
            "source_type": record.source_type,
            "source_title": record.title,
            "source_id": record.source_id,
            "tags": list(record.tags),
            "created_at": record.created_at,
            "chunk_index": index,
            "chunk_total": total_chunks,
        }
        documents.append(
            KnowledgeDocument(
                source_id=record.source_id,
                chunk_id=chunk_id,
                namespace=record.namespace,
                text=chunk,
                metadata=metadata,
            )
        )
    return documents


class PersistentCorpusStore:
    """Append-only corpus store used to hydrate the knowledge hub at startup."""

    def __init__(self, storage_path: str | Path, chunk_size: int = 700, chunk_overlap: int = 120) -> None:
        self.storage_path = Path(storage_path)
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap
        self._records: dict[str, StoredCorpusRecord] = {}
        self._load()

    def ingest(
        self,
        documents: list[CorpusDocumentInput],
        chunk_size: int | None = None,
        chunk_overlap: int | None = None,
    ) -> tuple[list[KnowledgeDocument], CorpusIngestResponse]:
        effective_chunk_size = chunk_size or self.chunk_size
        effective_chunk_overlap = chunk_overlap if chunk_overlap is not None else self.chunk_overlap
        effective_chunk_overlap = min(effective_chunk_overlap, max(effective_chunk_size - 1, 0))
        created_records: list[StoredCorpusRecord] = []
        skipped_source_ids: list[str] = []

        for document in documents:
            record = _to_record(document)
            existing = self._records.get(record.source_id)
            if existing is not None:
                skipped_source_ids.append(record.source_id)
                continue
            self._records[record.source_id] = record
            created_records.append(record)

        if created_records:
            self._append_records(created_records)

        knowledge_documents: list[KnowledgeDocument] = []
        chunk_summaries: list[CorpusChunkSummary] = []
        for record in created_records:
            documents_for_record = _build_chunk_documents(
                record,
                chunk_size=effective_chunk_size,
                chunk_overlap=effective_chunk_overlap,
            )
            knowledge_documents.extend(documents_for_record)
            chunk_summaries.extend(
                [
                    CorpusChunkSummary(
                        source_id=document.source_id,
                        chunk_id=document.chunk_id,
                        namespace=document.namespace,
                        char_count=len(document.text),
                        metadata=document.metadata,
                    )
                    for document in documents_for_record
                ]
            )

        response = CorpusIngestResponse(
            storage_path=str(self.storage_path),
            ingested_documents=len(created_records),
            skipped_documents=len(skipped_source_ids),
            created_chunks=len(chunk_summaries),
            source_ids=[record.source_id for record in created_records],
            skipped_source_ids=skipped_source_ids,
            namespaces=sorted({record.namespace for record in created_records}),
            chunks=chunk_summaries,
        )
        return knowledge_documents, response

    def list_documents(self) -> CorpusListResponse:
        items = [
            CorpusListItem(
                source_id=record.source_id,
                title=record.title,
                namespace=record.namespace,
                source_type=record.source_type,
                tags=record.tags,
                metadata=record.metadata,
                created_at=record.created_at,
                char_count=len(record.text),
            )
            for record in self._records.values()
        ]
        items.sort(key=lambda item: item.created_at, reverse=True)
        return CorpusListResponse(documents=items)

    def load_knowledge_documents(self) -> list[KnowledgeDocument]:
        documents: list[KnowledgeDocument] = []
        for record in self._records.values():
            documents.extend(
                _build_chunk_documents(
                    record,
                    chunk_size=self.chunk_size,
                    chunk_overlap=self.chunk_overlap,
                )
            )
        return documents

    def _load(self) -> None:
        if not self.storage_path.exists():
            return
        with self.storage_path.open("r", encoding="utf-8") as handle:
            for raw_line in handle:
                line = raw_line.strip()
                if not line:
                    continue
                record = StoredCorpusRecord.from_dict(json.loads(line))
                self._records[record.source_id] = record

    def _append_records(self, records: list[StoredCorpusRecord]) -> None:
        self.storage_path.parent.mkdir(parents=True, exist_ok=True)
        with self.storage_path.open("a", encoding="utf-8") as handle:
            for record in records:
                handle.write(json.dumps(record.to_dict(), ensure_ascii=True) + "\n")

