import re
from collections import Counter
from typing import Optional

from .models import ExampleSection, SectionType


SECTION_ALIASES: list[tuple[SectionType, tuple[str, ...]]] = [
    ("hook", ("hook", "开头", "引入", "标题", "痛点开场")),
    ("problem_scene", ("problem_scene", "痛点", "场景", "问题", "生活场景")),
    ("story_detail", ("story_detail", "故事", "细节", "过程", "经历")),
    ("product_bridge", ("product_bridge", "转产品", "过渡", "自然转场", "种草")),
    ("proof", ("proof", "证据", "背书", "效果", "验证")),
    ("closing", ("closing", "结尾", "cta", "收尾", "总结")),
]

SECTION_KEYWORDS: dict[SectionType, tuple[str, ...]] = {
