STOPWORDS = {
    "的",
    "了",
    "和",
    "是",
    "就",
    "都",
    "也",
    "很",
    "在",
    "我",
    "你",
    "他",
    "她",
    "它",
    "一个",
    "这个",
    "那个",
    "不是",
    "没有",
    "如果",
}


def normalize_text(text: str) -> str:
    return re.sub(r"\s+", " ", text.strip().lower())


def tokenize(text: str) -> list[str]:
    normalized = normalize_text(text)
    parts = re.findall(r"[a-zA-Z0-9]+|[\u4e00-\u9fff]", normalized)
    tokens: list[str] = []
    for index, part in enumerate(parts):
        if part in STOPWORDS:
            continue
        if not re.match(r"[\u4e00-\u9fff]", part):
            tokens.append(part)
        else:
            if index + 1 < len(parts) and re.match(r"[\u4e00-\u9fff]", parts[index + 1]):
                tokens.append(part + parts[index + 1])
            if index + 2 < len(parts) and re.match(r"[\u4e00-\u9fff]", parts[index + 1]) and re.match(
                r"[\u4e00-\u9fff]", parts[index + 2]
            ):
                tokens.append(part + parts[index + 1] + parts[index + 2])
    return [token for token in tokens if token not in STOPWORDS]


def cosine_sparse(left: str, right: str) -> float:
    left_counts = Counter(tokenize(left))
    right_counts = Counter(tokenize(right))
    if not left_counts or not right_counts:
        return 0.0
    common = set(left_counts) & set(right_counts)
    dot = sum(left_counts[token] * right_counts[token] for token in common)
    left_norm = math.sqrt(sum(value * value for value in left_counts.values()))
    right_norm = math.sqrt(sum(value * value for value in right_counts.values()))
    if left_norm == 0 or right_norm == 0:
        return 0.0
    return dot / (left_norm * right_norm)


def lexical_overlap(left: str, right: str) -> float:
    left_tokens = set(tokenize(left))
    right_tokens = set(tokenize(right))
    if not left_tokens or not right_tokens:
        return 0.0
    return len(left_tokens & right_tokens) / max(len(left_tokens), len(right_tokens))


def split_sections(content: str) -> list[ExampleSection]:
    markdown_sections = _split_markdown_sections(content)
    if markdown_sections:
        return markdown_sections
    paragraphs = [part.strip() for part in re.split(r"\n\s*\n+", content) if part.strip()]
    if not paragraphs:
        paragraphs = [content.strip()] if content.strip() else []
    sections: list[ExampleSection] = []
    total = len(paragraphs)
    for index, paragraph in enumerate(paragraphs):
        section_type = infer_section_type(paragraph, index, total)
        sections.append(ExampleSection(section_type=section_type, content=paragraph, order=index))
    return sections


def _split_markdown_sections(content: str) -> list[ExampleSection]:
    matches = list(re.finditer(r"(?m)^(#{1,4})\s+(.+?)\s*$", content))
    if not matches:
        return []
    sections: list[ExampleSection] = []
    for index, match in enumerate(matches):
        start = match.end()
        end = matches[index + 1].start() if index + 1 < len(matches) else len(content)
        title = match.group(2).strip()
        body = content[start:end].strip()
        if not body:
            continue
        section_type = section_type_from_title(title) or infer_section_type(body, index, len(matches))
        sections.append(ExampleSection(section_type=section_type, content=body, order=index))
    return sections


def section_type_from_title(title: str) -> Optional[SectionType]:
    title_lower = title.lower()
    for section_type, aliases in SECTION_ALIASES:
        if any(alias.lower() in title_lower for alias in aliases):
            return section_type
    return None


def infer_section_type(text: str, index: int, total: int) -> SectionType:
    scores: dict[SectionType, int] = {}
    for section_type, keywords in SECTION_KEYWORDS.items():
        if section_type in ("body", "title"):
            continue
        scores[section_type] = sum(1 for keyword in keywords if keyword in text)
    if index == 0:
        scores["hook"] = scores.get("hook", 0) + 2
    if total > 1 and index == total - 1:
        scores["closing"] = scores.get("closing", 0) + 1
    best_type, best_score = max(scores.items(), key=lambda item: item[1])
    return best_type if best_score > 0 else "body"


def summarize_outline(sections: list[ExampleSection]) -> list[str]:
    outline = []
    for section in sections:
        short = section.content.replace("\n", " ").strip()
        if len(short) > 42:
            short = short[:42] + "..."
        outline.append(f"{section.section_type}: {short}")
    return outline

