        or ["document_reference", "style_reference", "structure_reference"],
        risk_notes=_string_list(understanding_payload.get("risk_notes")),
    )

    raw_routes = payload.get("rewrite_routes")
    if not isinstance(raw_routes, list):
        raise ValueError("rewrite_routes must be a list")

    routes: list[RewriteRoute] = []
    seen_routes: set[str] = set()
    for item in raw_routes:
        if not isinstance(item, dict):
