    if chunks:
        return "\n".join(chunks)

    raise ValueError("Responses API response does not contain output text")


def normalize_rewrite_query(query: str) -> str:
    query = re.sub(r"\s+", " ", query).strip()
    return query[:240]


def route_order(route: str) -> int:
    order = [
        "topic_direct",
        "pain_scene",
        "emotion_hook",
        "life_detail",
        "structure_reference",
        "soft_product_bridge",
        "graph_expansion",
    ]
    return order.index(route) if route in order else 999


def _string_list(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, str):
        return [value]
    if not isinstance(value, list):
        return []
    return [str(item).strip() for item in value if str(item).strip()]


def _expand_terms(tokens: Union[set[str], list[str]]) -> list[str]:
