def context_pack_usages(store: JsonKnowledgeStore, item_id: str) -> list[dict[str, Any]]:
    usages: list[dict[str, Any]] = []
    for run in store.list_context_pack_runs(limit=200):
        for citation in run.citations:
            if citation.get("source_type") == "structured_item" and citation.get("item_id") == item_id:
                usages.append(
                    {
                        "context_pack_id": run.context_pack_id,
                        "template_code": run.template_code,
                        "created_at": run.created_at,
                        "snapshot_hash": run.snapshot_hash,
                    }
                )
                break
    return usages[:20]


def item_actions(status: str, has_usages: bool) -> list[str]:
    actions = ["save", "create_draft_revision", "search_debug"]
    if status == "draft":
        actions.extend(["submit_review", "delete_draft"])
    if status not in {"archived", "deprecated"}:
        actions.append("archive")
    if not has_usages:
        actions.append("delete")
    return actions


