    def feedback_summaries_for(self, target_type: str) -> dict[str, FeedbackSummary]:
        with self.lock:
            db = self._read_db()
            target_ids = sorted(
                {
                    str(item.get("target_id", ""))
                    for item in db["feedback"]
                    if item.get("target_type") == target_type and item.get("target_id")
                }
            )
        return {target_id: self.summarize_feedback(target_type, target_id) for target_id in target_ids}

    def list_versions(self, resource_type: Optional[str] = None, resource_id: Optional[str] = None) -> list[VersionRecord]:
        with self.lock:
            db = self._read_db()
            records = [VersionRecord.from_dict(item) for item in db["versions"]]
        if resource_type:
            records = [record for record in records if record.resource_type == resource_type]
        if resource_id:
            records = [record for record in records if record.resource_id == resource_id]
        records.sort(key=lambda item: (item.created_at, item.version_number), reverse=True)
        return records

    def add_context_pack_run(self, run: ContextPackRun) -> ContextPackRun:
        if not run.context_pack_id.strip():
            raise ValueError("context_pack_id is required")
        with self.lock:
            db = self._read_db()
            if self._find_index(db["context_pack_runs"], "context_pack_id", run.context_pack_id) is not None:
                raise ValueError(f"context pack run already exists: {run.context_pack_id}")
            db["context_pack_runs"].append(to_dict(run))
            self._append_version(
                db,
                resource_type="context_pack",
                resource_id=run.context_pack_id,
                snapshot=run.response_payload,
                change_type="create",
                change_note="create immutable context pack snapshot",
                created_by=run.created_by,
            )
            self._write_db(db)
            return run

    def get_context_pack_run(self, context_pack_id: str) -> Optional[ContextPackRun]:
        with self.lock:
            db = self._read_db()
            for item in db["context_pack_runs"]:
                if item.get("context_pack_id") == context_pack_id:
                    return ContextPackRun.from_dict(item)
        return None

    def list_context_pack_runs(self, limit: int = 100) -> list[ContextPackRun]:
        limit = max(1, min(int(limit), 500))
        with self.lock:
            db = self._read_db()
            records = [ContextPackRun.from_dict(item) for item in db["context_pack_runs"]]
        records.sort(key=lambda item: item.created_at, reverse=True)
        return records[:limit]

    def clear(self) -> None:
        with self.lock:
            self._write_db({key: list(value) for key, value in EMPTY_DB.items()})

    def _read_db(self) -> dict[str, list[dict[str, Any]]]:
        raw_text = self.path.read_text(encoding="utf-8")
        if not raw_text.strip():
            return {key: list(value) for key, value in EMPTY_DB.items()}
        raw = json.loads(raw_text)
        if isinstance(raw, list):
            raw = {"examples": raw}
        db: dict[str, list[dict[str, Any]]] = {}
        for key, value in EMPTY_DB.items():
            items = raw.get(key, value) if isinstance(raw, dict) else value
            db[key] = list(items) if isinstance(items, list) else []
        return db

    def _write_db(self, db: dict[str, list[dict[str, Any]]]) -> None:
        serialized = json.dumps(db, ensure_ascii=False, indent=2) + "\n"
        with tempfile.NamedTemporaryFile("w", encoding="utf-8", dir=str(self.path.parent), delete=False) as tmp:
            tmp.write(serialized)
            tmp.flush()
            os.fsync(tmp.fileno())
            temp_path = Path(tmp.name)
        os.replace(temp_path, self.path)

    def _import_legacy_examples_if_needed(self) -> None:
        if not DEFAULT_DATA_PATH.exists():
            return
        with self.lock:
            db = self._read_db()
            if db["examples"]:
                return
            try:
                legacy_raw = json.loads(DEFAULT_DATA_PATH.read_text(encoding="utf-8"))
            except json.JSONDecodeError:
                return
            if not isinstance(legacy_raw, list) or not legacy_raw:
                return
            for item in legacy_raw:
                if not isinstance(item, dict):
                    continue
                document = ExampleDocument.from_dict(item)
                db["examples"].append(to_dict(document))
                self._append_version(
                    db,
                    resource_type="example",
                    resource_id=document.document_id,
                    snapshot=to_dict(document),
                    change_type="legacy_import",
                    change_note="import from data/examples.json",
                    created_by="system",
                )
            self._write_db(db)

    def _append_version(
        self,
        db: dict[str, list[dict[str, Any]]],
        resource_type: str,
        resource_id: str,
        snapshot: dict[str, Any],
        change_type: str,
        change_note: str,
        created_by: str,
    ) -> None:
        version_number = 1 + sum(
            1
            for item in db["versions"]
            if item.get("resource_type") == resource_type and item.get("resource_id") == resource_id
        )
        db["versions"].append(
            to_dict(
                VersionRecord(
                    resource_type=resource_type,
                    resource_id=resource_id,
                    version_number=version_number,
                    snapshot=snapshot,
                    change_type=change_type,
                    change_note=change_note,
                    created_by=created_by,
                )
            )
        )

    @staticmethod
    def _find_index(items: list[dict[str, Any]], key: str, value: str) -> Optional[int]:
        for index, item in enumerate(items):
            if item.get(key) == value:
                return index
        return None

    @staticmethod
    def _matches_attribute_filters(item: StructuredItem, filters: dict[str, Any]) -> bool:
        for key, expected in filters.items():
            if item.attributes.get(key) != expected:
                return False
        return True

    @staticmethod
    def _structured_item_search_text(item: StructuredItem) -> str:
        return json.dumps(
            {
                "type_id": item.type_id,
                "title": item.title,
                "attributes": item.attributes,
                "tags": item.tags,
                "source": item.source,
                "metadata": item.metadata,
            },
            ensure_ascii=False,
        ).lower()


