def run_validation(store: JsonKnowledgeStore, payload: dict[str, Any]) -> dict[str, Any]:
    scope = str(payload.get("scope", "all"))
    issues: list[dict[str, Any]] = []
    checks = normalize_checks(payload.get("checks"), scope)
    if "structured" in checks:
        issues.extend(validate_structured(store))
    if "relations" in checks:
        issues.extend(validate_relations(store))
    if "example_corpus" in checks:
        issues.extend(validate_examples(store))
    if "links" in checks:
        issues.extend(validate_links(store))
    if "context_templates" in checks:
        issues.extend(validate_context_templates(store))
    status = "passed" if not issues else "warning"
    return {
        "run_id": str(uuid4()),
        "status": status,
        "scope": scope,
        "checks": checks,
        "summary": {
            "issue_count": len(issues),
            "error_count": sum(1 for item in issues if item.get("severity") == "error"),
            "warning_count": sum(1 for item in issues if item.get("severity", "warning") == "warning"),
        },
        "issues": issues,
    }


def normalize_checks(value: Any, scope: str) -> list[str]:
    if isinstance(value, list) and value:
        return [str(item) for item in value]
    if scope == "structured":
        return ["structured", "relations", "links"]
    if scope in {"corpus", "example_corpus"}:
        return ["example_corpus", "links"]
    if scope in {"context", "context_templates"}:
        return ["context_templates"]
    return ["structured", "relations", "example_corpus", "links", "context_templates"]


