def context_pack_usages(store: JsonKnowledgeStore, item_id: str) -> list[dict[str, Any]]:
    usages: list[dict[str, Any]] = []
    for run in store.list_context_pack_runs(limit=200):
        for citation in run.citations:
            if citation.get("source_type") == "structured_item" and citation.get("item_id") == item_id:
                usages.append(
                    {
                        "context_pack_id": run.context_pack_id,
                        "template_code": run.template_code,
                        "created_at": run.created_at,
                        "snapshot_hash": run.snapshot_hash,
                    }
                )
                break
    return usages[:20]


def item_actions(status: str, has_usages: bool) -> list[str]:
    actions = ["save", "create_draft_revision", "search_debug"]
    if status == "draft":
        actions.extend(["submit_review", "delete_draft"])
    if status not in {"archived", "deprecated"}:
        actions.append("archive")
    if not has_usages:
        actions.append("delete")
    return actions


def usage_warnings(usages: list[dict[str, Any]]) -> list[dict[str, Any]]:
    if not usages:
        return []
    return [
        {
            "code": "USED_BY_CONTEXT_PACK",
            "message": f"已有 {len(usages)} 次 Context Pack 使用过该知识，删除或大改前需要确认影响。",
        }
    ]


def validate_structured_item(item: Any) -> dict[str, Any]:
    issues = []
    if not item.title.strip():
        issues.append({"code": "MISSING_TITLE", "message": "标题不能为空。"})
    if not item.attributes:
        issues.append({"code": "EMPTY_ATTRIBUTES", "message": "结构化 attributes 为空。"})
    return {"status": "passed" if not issues else "warning", "issues": issues}


def dedupe_records(records: list[dict[str, Any]], key: str) -> list[dict[str, Any]]:
    seen: set[str] = set()
    result: list[dict[str, Any]] = []
    for record in records:
        value = str(record.get(key, ""))
        if value and value in seen:
            continue
        if value:
            seen.add(value)
        result.append(record)
    return result

