@dataclass
class PermissionDecision:
    allowed: bool
    role: str
    resource_type: str
    action: str
    reasons: list[str] = field(default_factory=list)


def normalize_role(role: str | None) -> str:
    value = (role or "admin").strip().lower()
    return value if value in ROLE_DESCRIPTIONS else "agent"


def can(role: str | None, resource_type: str, action: str, resource: dict[str, Any] | None = None) -> PermissionDecision:
    normalized_role = normalize_role(role)
    allowed_actions = ROLE_ALLOW.get(normalized_role, {}).get(resource_type, set())
    reasons: list[str] = []
    allowed = action in allowed_actions
    if not allowed:
        reasons.append(f"role {normalized_role} cannot {action} {resource_type}")
    if allowed and normalized_role == "agent" and action == "read" and resource:
        status = str(resource.get("status", ""))
        if status and status not in {"active", "published"}:
            allowed = False
            reasons.append("agent can only read active/published resources")
    if allowed and action in {"publish", "approve"} and resource:
        risk_level = str(resource.get("attributes", {}).get("risk_level", resource.get("metadata", {}).get("risk_level", ""))).lower()
        if risk_level in {"high", "critical"} and normalized_role not in {"admin", "reviewer"}:
            allowed = False
            reasons.append("high risk resource requires reviewer/admin")
    return PermissionDecision(
        allowed=allowed,
        role=normalized_role,
        resource_type=resource_type,
        action=action,
        reasons=reasons,
    )


def permission_matrix(role: str | None, resource_type: str, resource: dict[str, Any] | None = None) -> dict[str, Any]:
    normalized_role = normalize_role(role)
    actions = RESOURCE_ACTIONS.get(resource_type, [])
    decisions = {action: can(normalized_role, resource_type, action, resource) for action in actions}
    return {
        "role": normalized_role,
        "resource_type": resource_type,
        "can": {f"can_{action}": decision.allowed for action, decision in decisions.items()},
        "available_actions": [action for action, decision in decisions.items() if decision.allowed],
        "denied_reasons": {
            action: decision.reasons
            for action, decision in decisions.items()
            if not decision.allowed and decision.reasons
        },
    }


def all_roles_matrix() -> dict[str, Any]:
    return {
        "roles": ROLE_DESCRIPTIONS,
        "resources": RESOURCE_ACTIONS,
        "policies": {
            role: {resource: sorted(actions) for resource, actions in resources.items()}
            for role, resources in ROLE_ALLOW.items()
        },
    }

