                "message": "当前角色无权执行该动作。",
                "details": to_dict(decision),
            },
        }
    handler = ACTION_HANDLERS.get((resource_type, action))
    if handler is None:
        return {
            "ok": False,
            "action": action,
            "resource_type": resource_type,
            "resource_id": resource_id,
            "error": {"code": "ACTION_NOT_SUPPORTED", "message": "当前资源不支持该动作。"},
        }
    result = handler(store, resource_id, data, actor_id)
    return {
        "ok": True,
        "action": action,
        "resource_type": resource_type,
        "resource_id": resource_id,
        "result": result,
        "permission": to_dict(decision),
    }


