                "source": {"kind": "feedback_memory_candidate", "candidate_id": candidate.candidate_id},
                "metadata": {"candidate": to_dict(candidate), **dict(proposed.get("metadata", {}))},
            }
        ),
        created_by=actor_id,
    )
    updated = store.update_feedback_memory_candidate(
        resource_id,
        {
            "status": "published",
            "proposed_item": {**proposed, "published_item_id": item.item_id},
