def run_evaluation(store: JsonKnowledgeStore, payload: dict[str, Any]) -> dict[str, Any]:
    cases = list(payload.get("cases", []))
    if not cases:
        cases = default_cases(store)
    results = []
    for case in cases:
        if not isinstance(case, dict):
            continue
        kind = str(case.get("kind", "example_recall"))
        if kind == "context_pack":
            results.append(evaluate_context_pack_case(store, case))
        else:
            results.append(evaluate_example_recall_case(store, case))
    passed_count = sum(1 for item in results if item.get("passed"))
    return {
        "run_id": str(uuid4()),
        "status": "passed" if passed_count == len(results) else "warning",
        "summary": {
            "case_count": len(results),
            "passed_count": passed_count,
            "failed_count": len(results) - passed_count,
        },
        "results": results,
    }


def evaluate_example_recall_case(store: JsonKnowledgeStore, case: dict[str, Any]) -> dict[str, Any]:
    query = str(case.get("query", ""))
    top_k = int(case.get("top_k", 3))
    rewrite_mode = str(case.get("rewrite_mode", "rule"))
    expected_document_ids = {str(item) for item in case.get("expected_document_ids", [])}
    expected_title_contains = [str(item) for item in case.get("expected_title_contains", [])]
    response = ExampleRecallService(
        store.list_examples(),
        feedback_summaries=store.feedback_summaries_for("example"),
    ).search(SearchRequest(query=query, top_k=top_k, rewrite_mode=rewrite_mode, include_trace=True))
    actual_ids = [item.document_id for item in response.selected_examples]
    actual_titles = [item.title for item in response.selected_examples]
    passed = bool(response.selected_examples)
    if expected_document_ids:
        passed = passed and bool(expected_document_ids.intersection(actual_ids))
    for needle in expected_title_contains:
        passed = passed and any(needle in title for title in actual_titles)
    return {
        "case_id": str(case.get("case_id", query or uuid4())),
        "kind": "example_recall",
        "query": query,
        "passed": passed,
        "actual_document_ids": actual_ids,
        "actual_titles": actual_titles,
        "expected_document_ids": list(expected_document_ids),
        "trace": response.trace if case.get("include_trace", True) else {},
    }


def evaluate_context_pack_case(store: JsonKnowledgeStore, case: dict[str, Any]) -> dict[str, Any]:
    request_payload = dict(case.get("request", {}))
    request_payload.setdefault("persist", False)
    request_payload.setdefault("rewrite_mode", case.get("rewrite_mode", "rule"))
    response = ContextPackService(store).create(ContextPackRequest.from_dict(request_payload))
    required_slots = [str(item) for item in case.get("required_slots", ["example_references"])]
