        "kind": "context_pack",
        "query": response.query,
        "passed": not missing_slots,
        "missing_slots": missing_slots,
        "slot_counts": {
            slot_name: len(slot.get("items", [])) + len(slot.get("documents", []))
            for slot_name, slot in response.slots.items()
