def run_validation(store: JsonKnowledgeStore, payload: dict[str, Any]) -> dict[str, Any]:
    scope = str(payload.get("scope", "all"))
    issues: list[dict[str, Any]] = []
    checks = normalize_checks(payload.get("checks"), scope)
    if "structured" in checks:
        issues.extend(validate_structured(store))
    if "relations" in checks:
        issues.extend(validate_relations(store))
    if "example_corpus" in checks:
        issues.extend(validate_examples(store))
    if "links" in checks:
        issues.extend(validate_links(store))
    if "context_templates" in checks:
        issues.extend(validate_context_templates(store))
    status = "passed" if not issues else "warning"
    return {
        "run_id": str(uuid4()),
        "status": status,
        "scope": scope,
        "checks": checks,
        "summary": {
            "issue_count": len(issues),
            "error_count": sum(1 for item in issues if item.get("severity") == "error"),
            "warning_count": sum(1 for item in issues if item.get("severity", "warning") == "warning"),
        },
        "issues": issues,
    }


def normalize_checks(value: Any, scope: str) -> list[str]:
    if isinstance(value, list) and value:
        return [str(item) for item in value]
    if scope == "structured":
        return ["structured", "relations", "links"]
    if scope in {"corpus", "example_corpus"}:
        return ["example_corpus", "links"]
    if scope in {"context", "context_templates"}:
        return ["context_templates"]
    return ["structured", "relations", "example_corpus", "links", "context_templates"]


def validate_structured(store: JsonKnowledgeStore) -> list[dict[str, Any]]:
    issues: list[dict[str, Any]] = []
    types = {item.type_id for item in store.list_structured_types()}
    for item in store.search_structured_items(request_all()):
        if item.type_id not in types:
            issues.append(issue("STRUCTURED_TYPE_MISSING", "error", "structured_item", item.item_id, f"结构化条目引用了不存在的 type_id: {item.type_id}"))
        if not item.title.strip():
            issues.append(issue("MISSING_TITLE", "warning", "structured_item", item.item_id, "结构化条目标题为空。"))
        if item.status == "published":
            issues.append(issue("STATUS_ALIAS", "warning", "structured_item", item.item_id, "原型推荐使用 active/draft/archived，published 会被兼容但需迁移。"))
    return issues


def validate_relations(store: JsonKnowledgeStore) -> list[dict[str, Any]]:
    issues: list[dict[str, Any]] = []
    for relation in store.list_structured_relations():
        source = store.get_structured_item(relation.source_item_id)
        target = store.get_structured_item(relation.target_item_id)
        if source is None:
            issues.append(issue("RELATION_SOURCE_MISSING", "error", "structured_relation", relation.relation_id, "关系 source_item_id 不存在。"))
        if target is None:
            issues.append(issue("RELATION_TARGET_MISSING", "error", "structured_relation", relation.relation_id, "关系 target_item_id 不存在。"))
        if source is not None and source.status == "archived":
            issues.append(issue("RELATION_SOURCE_ARCHIVED", "warning", "structured_relation", relation.relation_id, "关系指向了 archived source item。"))
        if target is not None and target.status == "archived":
            issues.append(issue("RELATION_TARGET_ARCHIVED", "warning", "structured_relation", relation.relation_id, "关系指向了 archived target item。"))
