def context_pack_template_designer_view(store: JsonKnowledgeStore, template_id_or_code: str) -> dict[str, Any]:
    template = store.get_context_pack_template(template_id_or_code)
    if template is None and template_id_or_code == "article_generation_v1":
        template_payload = DEFAULT_CONTEXT_TEMPLATE
        versions = []
        active_version = DEFAULT_CONTEXT_TEMPLATE["template_version"]
        status = "builtin"
    elif template is None:
        raise KeyError(f"context pack template not found: {template_id_or_code}")
    else:
        template_payload = to_dict(template)
        versions = [to_dict(item) for item in store.list_context_pack_template_versions(template.template_id)]
        active_version = template.active_version
        status = template.status
    return {
        "view": {"mode": "designer", "title": template_payload.get("name", template_payload.get("template_code", template_id_or_code))},
        "data": {
            "template": template_payload,
            "active_version": active_version,
            "status": status,
            "versions": versions,
            "slot_preview": build_slot_preview(template_payload.get("slots", {})),
            "recent_context_usages": template_usages(store, template_payload.get("template_code", template_id_or_code)),
        },
        "schemas": {
            "template_schema": {
                "required": ["template_code", "slots"],
                "slot_source_values": ["structured", "example_corpus"],
            },
            "slot_schema": {
                "source": "structured|example_corpus",
                "type_codes": "list[str]",
                "top_k": "int",
                "filters": "object",
            },
        },
