        "available_actions": ["save_draft", "create_version", "publish_version", "preview_context_pack", "run_validation"],
        "warnings": [],
        "validation": {
            "status": "warning" if validate_context_templates(store) else "passed",
            "issues": validate_context_templates(store),
        },
        "jobs": [],
        "meta": {"api": "admin_bff", "resource": "context_pack_template", "template_id": template_id_or_code},
    }


def build_slot_preview(slots: dict[str, Any]) -> list[dict[str, Any]]:
    preview = []
    if not isinstance(slots, dict):
        return preview
    for slot_name, slot_config in slots.items():
        if not isinstance(slot_config, dict):
            continue
        preview.append(
            {
                "slot_name": slot_name,
                "source": slot_config.get("source", "structured"),
                "type_codes": slot_config.get("type_codes", slot_config.get("type_ids", [])),
                "top_k": slot_config.get("top_k"),
                "required": bool(slot_config.get("required", False)),
                "enabled": slot_config.get("enabled", True) is not False,
            }
        )
    return preview


def template_usages(store: JsonKnowledgeStore, template_code: str) -> list[dict[str, Any]]:
    usages = []
    for run in store.list_context_pack_runs(limit=200):
        if run.template_code != template_code:
            continue
        usages.append(
            {
                "context_pack_id": run.context_pack_id,
                "template_version": run.template_version,
                "created_at": run.created_at,
                "snapshot_hash": run.snapshot_hash,
            }
        )
    return usages[:20]

